-- AI/ML pathway (Cipher Division) Act 15 -- "Training Deep Networks" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway. Part of Arc III
-- ("Neural Systems", Acts 13-18). Builds on the World row already updated
-- by 20260812010000_ai_acts11_15_world_narrative.sql
-- (world-ai-training-deep-networks, act-ai-3). Does not insert into
-- worlds, acts or pathways -- those rows already exist.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-ai-training-deep-networks', 'world-ai-training-deep-networks', 'training-deep-networks', '15A - Training Deep Networks', 'Make deep network training actually reliable: initialization, normalization, dropout and weight decay, early stopping, learning rate schedules and checkpoints -- and prove, the hard way, that a suspiciously good number is not the same thing as an honest one.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-ai-training-deep-networks-1', 'campaign-ai-training-deep-networks', 'starting-right', 'Starting Right', 'Initialization, vanishing and exploding gradients, and the normalization techniques that keep a deep network''s signal from shrinking or blowing up before it ever finishes a forward pass.', 1),
  ('operation-ai-training-deep-networks-2', 'campaign-ai-training-deep-networks', 'stopping-right', 'Stopping Right', 'Dropout, weight decay, early stopping, learning rate schedules and checkpoints -- the discipline that decides whether a trained network generalizes, or only memorizes.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-ai-training-deep-networks-01', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'initialization', 'Initialization', 'Cipher Division''s first real deep network trains beautifully -- suspiciously beautifully. Before any number from it gets trusted, stress-testing starts at the very first line: how its weights are initialized.', 'beginner', ARRAY['maya','elena'], null, null, '{"type":"simulation","simulationId":"initialization-sim"}'::jsonb, '{"xp":260,"credits":60}'::jsonb, false, 1),
  ('mission-ai-training-deep-networks-02', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'vanishing-gradients', 'Vanishing Gradients', 'A gradient signal chained through enough layers of the wrong activation function can shrink to nothing before it ever reaches the earliest layers -- and those layers simply stop learning.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-training-deep-networks-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"vanishing-gradients-sim"}'::jsonb, '{"xp":270,"credits":60}'::jsonb, false, 2),
  ('mission-ai-training-deep-networks-03', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'exploding-gradients', 'Exploding Gradients', 'The opposite failure is loud instead of quiet: a gradient signal that grows without bound, until the loss spikes to NaN and an afternoon of training is gone in one epoch.', 'beginner', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-training-deep-networks-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"exploding-gradients-sim"}'::jsonb, '{"xp":270,"credits":65}'::jsonb, false, 3),
  ('mission-ai-training-deep-networks-04', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'normalization', 'Normalization', 'Feed a network features on wildly different scales and its first layer has to fight the data before it can even start learning the task. Normalization is the fix that comes before the network ever sees a single example.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"normalization-sim"}'::jsonb, '{"xp":280,"credits":65}'::jsonb, false, 4),
  ('mission-ai-training-deep-networks-05', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'batch-norm', 'Batch Norm', 'Every layer after the first watches its inputs shift as the layers before it keep changing. Batch Normalization steadies that moving target, one mini-batch at a time.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"batch-norm-sim"}'::jsonb, '{"xp":280,"credits":65}'::jsonb, false, 5),
  ('mission-ai-training-deep-networks-06', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-1', 'layer-norm', 'Layer Norm', 'Batch Normalization needs a real batch to work well. Layer Normalization does not -- it finds its statistics inside a single example instead.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"layer-norm-sim"}'::jsonb, '{"xp":290,"credits":70}'::jsonb, false, 6),
  ('mission-ai-training-deep-networks-07', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'dropout', 'Dropout', 'Making training stable is only half the job. Starting now, the question becomes whether the network is learning the task, or just memorizing the training set -- and Dropout is the first defense against the second.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"dropout-sim"}'::jsonb, '{"xp":290,"credits":70}'::jsonb, false, 7),
  ('mission-ai-training-deep-networks-08', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'weight-decay', 'Weight Decay', 'Large weights are often a sign of a model fitting noise instead of signal. Weight decay penalizes them directly, right inside the loss function being minimized.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"weight-decay-sim"}'::jsonb, '{"xp":300,"credits":70}'::jsonb, false, 8),
  ('mission-ai-training-deep-networks-09', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'early-stopping', 'Early Stopping', 'Every training run has a moment where validation loss stops improving and starts climbing, even as training loss keeps falling. Early stopping is the discipline of noticing that moment and stopping there.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"early-stopping-sim"}'::jsonb, '{"xp":300,"credits":75}'::jsonb, false, 9),
  ('mission-ai-training-deep-networks-10', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'lr-schedules', 'LR Schedules', 'A single fixed learning rate is rarely right for an entire training run. Learning rate schedules change it on purpose, phase by phase, instead of leaving it to chance.', 'intermediate', ARRAY['elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"lr-schedules-sim"}'::jsonb, '{"xp":310,"credits":75}'::jsonb, false, 10),
  ('mission-ai-training-deep-networks-11', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'checkpoints', 'Checkpoints', 'Early stopping only works if there is something saved to stop at. Checkpoints are what make the best version of a network recoverable, not just whatever it happened to be when training finally halted.', 'intermediate', ARRAY['elena','byte'], '{"requiredMissionIds":["mission-ai-training-deep-networks-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"checkpoints-sim"}'::jsonb, '{"xp":310,"credits":75}'::jsonb, false, 11),
  ('mission-ai-training-deep-networks-12', 'world-ai-training-deep-networks', 'campaign-ai-training-deep-networks', 'operation-ai-training-deep-networks-2', 'overfit', 'Overfit', 'Trained past every safeguard in this Act, the deep network scores 99.8% on its own training data. Cipher Division has to prove that number is real, or find exactly what fixes it, before anyone trusts a single output.', 'boss', ARRAY['maya','elena'], '{"requiredMissionIds":["mission-ai-training-deep-networks-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"overfit-boss-sim"}'::jsonb, '{"xp":820,"credits":180,"badgeIds":["overfit"],"skillXp":{"deep_learning":55,"ai_ml_fundamentals":20}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-ai-training-deep-networks-01', 1, 'maya', 'Cipher Division''s first real deep network just finished training. The loss curve is beautiful -- smooth, fast, and it converged in a fraction of the time we budgeted for it.'),
  ('mission-ai-training-deep-networks-01', 2, 'elena', 'Beautiful is not the word I would use yet. Suspicious is. Before anyone quotes that number outside this room, I want it stress-tested from every angle we have -- the same way Maya made all of us stress-test a spreadsheet''s 99% score back in Act 6.'),
  ('mission-ai-training-deep-networks-01', 3, 'maya', 'Good. That instinct used to be mine to enforce. Watching it become yours is the actual proof the lesson landed.'),
  ('mission-ai-training-deep-networks-01', 4, 'elena', 'Stress-testing a deep network starts before a single training example is even seen -- at how its weights are initialized. Set every weight to zero, or all to the same value, and every neuron in a layer computes the identical thing forever. The network never breaks that symmetry, no matter how long it trains.'),
  ('mission-ai-training-deep-networks-01', 5, 'elena', 'The fix is small random values, scaled to the size of the layer -- schemes like Xavier/Glorot or He initialization. Too small and signals vanish before they reach the last layer. Too large and they explode. Getting this one number right is the first item on the stress-test list.'),

  ('mission-ai-training-deep-networks-02', 1, 'elena', 'Initialization only prevents one failure. A deep enough network can still lose its gradient signal on the way back through many layers, even when initialization was done correctly. This is called the vanishing gradient problem.'),
  ('mission-ai-training-deep-networks-02', 2, 'byte', 'Same general category of gradient failure we looked at last Act, when we ruled it out for Echo. Today it is an ordinary training bug to fix, not a mystery to solve. No connection intended.'),
  ('mission-ai-training-deep-networks-02', 3, 'elena', 'Each layer''s gradient gets multiplied by the derivative of its activation function during backpropagation. Chain enough small derivatives together -- saturating activations like sigmoid or tanh are the classic culprit -- and the product shrinks toward zero by the time it reaches the earliest layers.'),
  ('mission-ai-training-deep-networks-02', 4, 'elena', 'The signature is unmistakable once you know to look for it: the last few layers keep learning normally while the first few layers'' weights barely move at all, epoch after epoch.'),

  ('mission-ai-training-deep-networks-03', 1, 'elena', 'The opposite failure is exploding gradients. Instead of shrinking to nothing, the gradient signal grows without bound as it passes backward through the layers, and the weight updates become enormous.'),
  ('mission-ai-training-deep-networks-03', 2, 'byte', 'The signature is loud, not quiet. Loss suddenly spikes to a huge number, or turns into NaN outright, sometimes after training looked perfectly stable for dozens of epochs.'),
  ('mission-ai-training-deep-networks-03', 3, 'elena', 'Common causes: weights initialized too large, a learning rate set too high, or very deep or recurrent architectures where the same multiplication compounds many times. The fix set is small and specific: gradient clipping, which caps the size of the gradient before it is applied, a lower learning rate, and correct initialization.'),

  ('mission-ai-training-deep-networks-04', 1, 'elena', 'Before either kind of gradient failure gets a chance to show up, one basic habit prevents a large share of the damage: normalizing the input data itself, so every feature sits on a comparable scale before the network ever sees it.'),
  ('mission-ai-training-deep-networks-04', 2, 'elena', 'Feed a network raw features where one column ranges from 0 to 1 and another ranges from 0 to 100,000, and the network''s first layer has to learn wildly different weight scales just to treat them fairly -- which makes training slower and less stable than it needs to be.'),
  ('mission-ai-training-deep-networks-04', 3, 'elena', 'The fix is simple: rescale every feature, typically to zero mean and unit variance, or to a fixed range like 0 to 1, before training starts. This is input normalization, the general principle. What Batch Norm and Layer Norm do next is the same idea, applied inside the network itself, layer by layer, not just at the input.'),

  ('mission-ai-training-deep-networks-05', 1, 'elena', 'Input normalization only fixes the very first layer''s view of the data. Every layer after that sees activations whose scale keeps shifting as the layers before it keep updating during training -- a moving target called internal covariate shift.'),
  ('mission-ai-training-deep-networks-05', 2, 'elena', 'Batch Normalization fixes it layer by layer: for each mini-batch, it normalizes that layer''s activations to zero mean and unit variance across the batch, then applies two small learnable parameters to rescale and shift them back into whatever range actually works best.'),
  ('mission-ai-training-deep-networks-05', 3, 'elena', 'The batch dependency is the part to remember. Batch Norm''s statistics come from the current mini-batch during training, but at inference there is often only one example at a time, so it switches to running averages collected during training instead.'),

  ('mission-ai-training-deep-networks-06', 1, 'elena', 'Batch Norm''s dependence on batch statistics is exactly the problem when batch size is small, or when examples in a batch are not really comparable to each other, as with variable-length sequences.'),
  ('mission-ai-training-deep-networks-06', 2, 'elena', 'Layer Normalization solves it by changing which dimension gets normalized: instead of computing statistics across the batch for each feature, it computes mean and variance across all the features of a single example, independently for every example.'),
  ('mission-ai-training-deep-networks-06', 3, 'elena', 'That makes Layer Norm''s behavior identical whether the batch size is 4 or 4,000, and identical at training time and inference time -- no running averages required. The tradeoff is that it can behave less predictably on architectures Batch Norm was originally designed for, like plain convolutional networks.'),

  ('mission-ai-training-deep-networks-07', 1, 'elena', 'Everything up to here has been about making training stable. Starting now, the focus shifts: making sure what gets learned actually generalizes, instead of just memorizing the training set.'),
  ('mission-ai-training-deep-networks-07', 2, 'elena', 'Dropout is the simplest tool for that. During training, it randomly zeroes out a fraction of a layer''s activations on every forward pass -- commonly 20 to 50 percent -- forcing the rest of the network to not depend too heavily on any single neuron.'),
  ('mission-ai-training-deep-networks-07', 3, 'elena', 'At inference, dropout is turned off entirely, and the activations are scaled to account for the fact that all neurons are active again. Skip that step and predictions will not match what training suggested they should.'),

  ('mission-ai-training-deep-networks-08', 1, 'elena', 'Dropout regularizes by randomness. Weight decay regularizes by penalty: a term proportional to the sum of the squared weights gets added directly to the loss function being minimized.'),
  ('mission-ai-training-deep-networks-08', 2, 'elena', 'The effect is that every training step nudges weights slightly smaller, in addition to whatever the actual task loss demands. Large weights, which are often a sign a model is fitting noise instead of signal, get discouraged directly.'),
  ('mission-ai-training-deep-networks-08', 3, 'elena', 'Too little weight decay and it does nothing useful. Too much and it fights the real signal, and the model underfits instead. It is a dial, not a switch, and it is usually tuned on the validation set, never the test set.'),

  ('mission-ai-training-deep-networks-09', 1, 'elena', 'Dropout and weight decay change how the network is built. Early stopping changes when you stop building it -- and it needs nothing more than the validation split every network in this Act has been using.'),
  ('mission-ai-training-deep-networks-09', 2, 'elena', 'Watch both curves during training: training loss almost always keeps falling, sometimes toward zero. Validation loss falls too, for a while -- then, past some point, it starts rising again even as training loss keeps dropping. That gap opening up is the model starting to memorize instead of generalize.'),
  ('mission-ai-training-deep-networks-09', 3, 'elena', 'Early stopping is the simple rule that follows: keep the checkpoint from the epoch where validation loss was lowest, and stop training there, instead of training until training loss looks perfect.'),

  ('mission-ai-training-deep-networks-10', 1, 'elena', 'One setting has been sitting fixed under every mission so far: the learning rate. A single fixed value is rarely the best choice for an entire training run.'),
  ('mission-ai-training-deep-networks-10', 2, 'elena', 'Too high a learning rate early on can cause the instability already covered -- loss spikes, even exploding gradients. Too low a learning rate late in training wastes time creeping toward a minimum it could have reached faster, or gets stuck oscillating around it without ever settling.'),
  ('mission-ai-training-deep-networks-10', 3, 'elena', 'A learning rate schedule changes the rate over time instead of leaving it fixed: a brief warmup that ramps up gradually at the very start, then a decay -- step-wise, or smooth like cosine annealing -- that lowers it as training progresses and the model gets closer to a good solution.'),

  ('mission-ai-training-deep-networks-11', 1, 'elena', 'Early stopping only works if there is actually something to stop at -- a saved copy of the model from that best epoch, not just the weights sitting in memory when training finally halts.'),
  ('mission-ai-training-deep-networks-11', 2, 'byte', 'That is what checkpoints are. A checkpoint saves the model''s weights, the optimizer state, and the current epoch and configuration, at regular intervals or whenever validation performance improves.'),
  ('mission-ai-training-deep-networks-11', 3, 'elena', 'Without checkpoints, a crashed run loses everything, and early stopping has nothing to actually stop at except whatever epoch happened to be saved last. With checkpoints, Cipher Division can always recover the actual best version of a network, not just whatever it happened to be at when training ended.'),

  ('mission-ai-training-deep-networks-12', 1, 'elena', 'Stress test complete. I trained the deep network far past where every safeguard in this Act says to stop -- no dropout, no weight decay, no early stopping, run twice as long as it needed.'),
  ('mission-ai-training-deep-networks-12', 2, 'maya', 'And?'),
  ('mission-ai-training-deep-networks-12', 3, 'elena', 'Training accuracy: 99.8 percent. Almost perfect. Which is exactly the number that gets a room excited, and exactly the number this Act has spent eleven missions teaching everyone not to trust on sight.'),
  ('mission-ai-training-deep-networks-12', 4, 'maya', 'Then do not tell me the number yet. Prove it, the same way Arjun proved the 99% score was fake back in Act 6. Same discipline. Different model, thousands of parameters instead of a spreadsheet.'),
  ('mission-ai-training-deep-networks-12', 5, 'elena', 'Three checks: what the training and validation curves actually show side by side, which technique from this Act would actually fix whatever they show, and whether that fix survives an honest, held-out evaluation afterward, not just an assertion that it worked.'),
  ('mission-ai-training-deep-networks-12', 6, 'maya', 'Run it. A stable, honestly-trained network is finally ready to leave toy examples behind. Cipher Division needs a real framework next, not hand-written training loops.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-ai-training-deep-networks-01-o1', 'mission-ai-training-deep-networks-01', 1, 'Diagnose the symmetry trap', 'Find the evidence showing what happens when every weight in a layer starts at the same value.'),
  ('mission-ai-training-deep-networks-01-o2', 'mission-ai-training-deep-networks-01', 2, 'Choose the fix', 'Identify what scaled random initialization schemes like Xavier or He actually protect against.'),

  ('mission-ai-training-deep-networks-02-o1', 'mission-ai-training-deep-networks-02', 1, 'Diagnose the vanishing signature', 'Find the evidence that shows a network''s early layers have stopped learning while its later layers have not.'),
  ('mission-ai-training-deep-networks-02-o2', 'mission-ai-training-deep-networks-02', 2, 'Identify the fix', 'Choose the change that would most directly address vanishing gradients caused by saturating activations.'),

  ('mission-ai-training-deep-networks-03-o1', 'mission-ai-training-deep-networks-03', 1, 'Diagnose the explosion', 'Find the evidence that confirms a network''s gradients are exploding, not failing some other way.'),
  ('mission-ai-training-deep-networks-03-o2', 'mission-ai-training-deep-networks-03', 2, 'Identify the fix', 'Choose the technique that directly caps runaway gradient updates.'),

  ('mission-ai-training-deep-networks-04-o1', 'mission-ai-training-deep-networks-04', 1, 'Explain the consequence', 'Identify what unnormalized, wildly-scaled input features actually do to training.'),
  ('mission-ai-training-deep-networks-04-o2', 'mission-ai-training-deep-networks-04', 2, 'Diagnose the fix', 'Find the evidence that shows normalizing input features stabilized an unstable training run.'),

  ('mission-ai-training-deep-networks-05-o1', 'mission-ai-training-deep-networks-05', 1, 'Define Batch Norm', 'Identify exactly what Batch Normalization computes and rescales.'),
  ('mission-ai-training-deep-networks-05-o2', 'mission-ai-training-deep-networks-05', 2, 'Diagnose the small-batch failure', 'Find the evidence that explains why Batch Norm statistics become unstable with a very small batch size.'),

  ('mission-ai-training-deep-networks-06-o1', 'mission-ai-training-deep-networks-06', 1, 'Define Layer Norm', 'Identify what dimension Layer Normalization actually computes its statistics across.'),
  ('mission-ai-training-deep-networks-06-o2', 'mission-ai-training-deep-networks-06', 2, 'Match technique to scenario', 'Decide, scenario by scenario, whether Batch Norm or Layer Norm actually fits better.'),

  ('mission-ai-training-deep-networks-07-o1', 'mission-ai-training-deep-networks-07', 1, 'Define Dropout', 'Identify how Dropout actually improves generalization during training.'),
  ('mission-ai-training-deep-networks-07-o2', 'mission-ai-training-deep-networks-07', 2, 'Diagnose the deployment bug', 'Find the evidence explaining why a deployed model gives inconsistent answers to the same input.'),

  ('mission-ai-training-deep-networks-08-o1', 'mission-ai-training-deep-networks-08', 1, 'Define weight decay', 'Identify the mechanism by which weight decay regularizes a network.'),
  ('mission-ai-training-deep-networks-08-o2', 'mission-ai-training-deep-networks-08', 2, 'Judge the before/after', 'Find the evidence that shows weight decay actually closing the gap between training and validation performance.'),

  ('mission-ai-training-deep-networks-09-o1', 'mission-ai-training-deep-networks-09', 1, 'Find the overfit point', 'Find the evidence that pinpoints where validation loss starts rising while training loss keeps falling.'),
  ('mission-ai-training-deep-networks-09-o2', 'mission-ai-training-deep-networks-09', 2, 'Define early stopping', 'Identify exactly what early stopping actually saves.'),

  ('mission-ai-training-deep-networks-10-o1', 'mission-ai-training-deep-networks-10', 1, 'Explain the schedule', 'Identify why lowering the learning rate over the course of training actually helps.'),
  ('mission-ai-training-deep-networks-10-o2', 'mission-ai-training-deep-networks-10', 2, 'Match phase to purpose', 'Sort each learning-rate behavior into warmup, decay, or constant.'),

  ('mission-ai-training-deep-networks-11-o1', 'mission-ai-training-deep-networks-11', 1, 'Define a checkpoint', 'Identify everything a complete training checkpoint actually needs to save.'),
  ('mission-ai-training-deep-networks-11-o2', 'mission-ai-training-deep-networks-11', 2, 'Diagnose the recovery gap', 'Find the evidence explaining what can and cannot be recovered after a crash, given what the last checkpoint saved.'),

  ('mission-ai-training-deep-networks-12-o1', 'mission-ai-training-deep-networks-12', 1, 'Diagnose the overfit signature', 'Determine whether the deep network''s training and validation curves show real overfitting, not just strong training performance.'),
  ('mission-ai-training-deep-networks-12-o2', 'mission-ai-training-deep-networks-12', 2, 'Choose the fix', 'Identify which regularization and training-discipline changes from this Act would actually correct the overfitting shown in the curves.'),
  ('mission-ai-training-deep-networks-12-o3', 'mission-ai-training-deep-networks-12', 3, 'Confirm the fix with honest evaluation', 'Judge whether a held-out, honest test-set comparison actually proves the fix improved generalization.'),
  ('mission-ai-training-deep-networks-12-o4', 'mission-ai-training-deep-networks-12', 4, 'Synthesize the verdict', 'Having diagnosed the overfit signature, chosen the fix, and confirmed it with honest evaluation, state Cipher Division''s verdict on the network.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-ai-training-deep-networks-01-o1-c1', 'mission-ai-training-deep-networks-01-o1', 1, 'investigation', 'A network was initialized with every weight in a layer set to the same value. Which evidence directly shows the failure that causes?', '{"evidence":[{"id":"e1","label":"Weight log","detail":"After 50 training epochs, every neuron in the first hidden layer still outputs the exact identical value for every input"},{"id":"e2","label":"Loss log","detail":"Training loss has barely moved from its starting value for over 50 epochs"},{"id":"e3","label":"Facilities log","detail":"GPU temperature has stayed within normal operating range"}],"question":"A network was initialized with every weight in a layer set to the same value. Which evidence directly shows the failure that causes?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-training-deep-networks-01-o2-c1', 'mission-ai-training-deep-networks-01-o2', 1, 'multiple_choice', 'Random initialization scaled to the size of the layer exists mainly to...', '{"question":"Random initialization scaled to the size of the layer (schemes like Xavier/Glorot or He initialization) exists mainly to...","options":[{"id":"a","text":"Make the code shorter to write"},{"id":"b","text":"Keep the scale of activations and gradients from shrinking or growing wildly as signals pass through many stacked layers"},{"id":"c","text":"Reduce how much training data is needed"},{"id":"d","text":"Remove the need for a loss function"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-training-deep-networks-02-o1-c1', 'mission-ai-training-deep-networks-02-o1', 1, 'investigation', 'Which evidence shows this network is suffering from vanishing gradients in its early layers?', '{"evidence":[{"id":"e1","label":"Gradient norms log","detail":"Layer 8, near the output, has a gradient norm of 0.42. Layer 1, near the input, has a gradient norm of 0.00003 and stays there epoch after epoch"},{"id":"e2","label":"Activation log","detail":"Early layers use sigmoid activations that saturate heavily on most inputs"},{"id":"e3","label":"Data log","detail":"Training set size is 50,000 examples, considered adequate for the task"}],"question":"Which evidence shows this network is suffering from vanishing gradients in its early layers?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-ai-training-deep-networks-02-o2-c1', 'mission-ai-training-deep-networks-02-o2', 1, 'multiple_choice', 'Which change would most directly help fix vanishing gradients caused by saturating activations?', '{"question":"Which change would most directly help fix vanishing gradients caused by saturating activations in a deep network?","options":[{"id":"a","text":"Add more saturating sigmoid layers"},{"id":"b","text":"Switch early layers to a non-saturating activation like ReLU, and use normalization to keep signals in a healthy range"},{"id":"c","text":"Reduce the learning rate to exactly zero"},{"id":"d","text":"Remove the loss function entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-training-deep-networks-03-o1-c1', 'mission-ai-training-deep-networks-03-o1', 1, 'investigation', 'Which evidence best confirms this is exploding gradients rather than some other kind of failure?', '{"evidence":[{"id":"e1","label":"Training log","detail":"Loss decreased normally through epoch 12, then jumped to NaN at epoch 13 with no code changes"},{"id":"e2","label":"Weight norm log","detail":"Average weight magnitude doubled every epoch for the three epochs before the NaN appeared"},{"id":"e3","label":"Dataset log","detail":"No new data was added after epoch 10"}],"question":"Which evidence best confirms this is exploding gradients rather than some other kind of failure?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-training-deep-networks-03-o2-c1', 'mission-ai-training-deep-networks-03-o2', 1, 'multiple_choice', 'Which technique directly targets exploding gradients?', '{"question":"Which technique directly targets exploding gradients by capping how large a gradient update is allowed to be?","options":[{"id":"a","text":"Dropout"},{"id":"b","text":"Gradient clipping"},{"id":"c","text":"Data augmentation"},{"id":"d","text":"Increasing the batch size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-training-deep-networks-04-o1-c1', 'mission-ai-training-deep-networks-04-o1', 1, 'multiple_choice', 'What is the most likely practical consequence of unnormalized, wildly-scaled features?', '{"question":"Training data has one feature ranging 0 to 1 and another ranging 0 to 100000, fed into a network unnormalized. What is the most likely practical consequence?","options":[{"id":"a","text":"No effect, networks are scale-invariant"},{"id":"b","text":"Training converges more slowly and less stably, since the network must learn very different weight scales for each feature"},{"id":"c","text":"The network refuses to train at all, always"},{"id":"d","text":"Accuracy improves automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-04-o2-c1', 'mission-ai-training-deep-networks-04-o2', 1, 'investigation', 'Which evidence points to unnormalized input scale as the root cause of the unstable training?', '{"evidence":[{"id":"e1","label":"Feature audit","detail":"Income column raw range is 0 to 500000, age column raw range is 18 to 90, no scaling applied to either"},{"id":"e2","label":"Training log before fix","detail":"Loss oscillates without shrinking across 100 epochs"},{"id":"e3","label":"Training log after fix","detail":"After z-score normalizing both features, loss decreases smoothly and converges by epoch 40"}],"question":"Which evidence points to unnormalized input scale as the root cause of the unstable training?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-ai-training-deep-networks-05-o1-c1', 'mission-ai-training-deep-networks-05-o1', 1, 'multiple_choice', 'Batch Normalization normalizes the activations of a layer by...', '{"question":"Batch Normalization normalizes the activations of a layer by...","options":[{"id":"a","text":"Removing outlier training examples from the batch"},{"id":"b","text":"Computing the mean and variance across the current mini-batch for each feature, then rescaling with learnable parameters"},{"id":"c","text":"Sorting activations from smallest to largest"},{"id":"d","text":"Discarding half the activations at random"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-05-o2-c1', 'mission-ai-training-deep-networks-05-o2', 1, 'investigation', 'Which evidence explains why Batch Norm statistics are unusually unstable in this run?', '{"evidence":[{"id":"e1","label":"Training config","detail":"Batch size was set to 4 due to GPU memory limits"},{"id":"e2","label":"Batch Norm stats log","detail":"Per-batch mean and variance vary wildly between consecutive batches, since each mini-batch contains only 4 examples"},{"id":"e3","label":"Data quality report","detail":"Training labels were manually verified before training"}],"question":"Which evidence explains why Batch Norm statistics are unusually unstable in this run?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-training-deep-networks-06-o1-c1', 'mission-ai-training-deep-networks-06-o1', 1, 'multiple_choice', 'Layer Normalization computes its mean and variance across...', '{"question":"Layer Normalization computes its mean and variance across...","options":[{"id":"a","text":"The entire training set"},{"id":"b","text":"All the features of a single example, independent of batch size"},{"id":"c","text":"Only the first feature of every example"},{"id":"d","text":"Random subsets of the batch"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-06-o2-c1', 'mission-ai-training-deep-networks-06-o2', 1, 'drag_and_drop', 'Sort each scenario into whichever normalization fits better.', '{"items":[{"id":"i1","text":"A large-batch image classifier trained with batch size 256"},{"id":"i2","text":"A sequence model trained with batch size 2 due to memory limits"},{"id":"i3","text":"A model that must behave identically between training and single-example inference"},{"id":"i4","text":"A convolutional network where batch statistics are stable and plentiful"}],"targets":[{"id":"batch_norm","label":"Batch Norm fits better"},{"id":"layer_norm","label":"Layer Norm fits better"}]}'::jsonb, '{"correctMapping":{"i1":"batch_norm","i2":"layer_norm","i3":"layer_norm","i4":"batch_norm"}}'::jsonb),

  ('mission-ai-training-deep-networks-07-o1-c1', 'mission-ai-training-deep-networks-07-o1', 1, 'multiple_choice', 'Dropout helps a network generalize better mainly by...', '{"question":"Dropout helps a network generalize better mainly by...","options":[{"id":"a","text":"Permanently deleting weak neurons from the network"},{"id":"b","text":"Randomly zeroing a fraction of activations during training so the network cannot over-rely on any single neuron or fixed combination of neurons"},{"id":"c","text":"Increasing the learning rate over time"},{"id":"d","text":"Adding more training data automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-07-o2-c1', 'mission-ai-training-deep-networks-07-o2', 1, 'investigation', 'Which evidence explains why the deployed model gives inconsistent answers to the same input?', '{"evidence":[{"id":"e1","label":"Inference log","detail":"The same input produces different output probabilities on repeated calls, with no randomness expected"},{"id":"e2","label":"Config log","detail":"Dropout layers remained active during the inference deployment instead of being disabled"},{"id":"e3","label":"Hardware log","detail":"Server GPU utilization is at 40 percent"}],"question":"Which evidence explains why the deployed model gives inconsistent answers to the same input?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-training-deep-networks-08-o1-c1', 'mission-ai-training-deep-networks-08-o1', 1, 'multiple_choice', 'Weight decay works by...', '{"question":"Weight decay, also called L2 regularization, works by...","options":[{"id":"a","text":"Removing training examples with large values"},{"id":"b","text":"Adding a penalty proportional to the squared weight magnitudes to the loss, encouraging smaller weights"},{"id":"c","text":"Randomly disabling neurons during training"},{"id":"d","text":"Increasing the batch size automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-08-o2-c1', 'mission-ai-training-deep-networks-08-o2', 1, 'investigation', 'Which evidence shows weight decay closing the gap between training and validation performance?', '{"evidence":[{"id":"e1","label":"Weight audit, no weight decay","detail":"Average weight magnitude is 4.8, training accuracy 99.9 percent, validation accuracy 81 percent"},{"id":"e2","label":"Weight audit, with weight decay added","detail":"Average weight magnitude drops to 1.1, training accuracy 96 percent, validation accuracy 90 percent"},{"id":"e3","label":"Hardware log","detail":"The identical GPU was used for both training runs"}],"question":"Which evidence shows weight decay closing the gap between training and validation performance?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-training-deep-networks-09-o1-c1', 'mission-ai-training-deep-networks-09-o1', 1, 'investigation', 'At what point does the evidence show the model beginning to overfit?', '{"evidence":[{"id":"e1","label":"Training log, epochs 1 to 10","detail":"Training loss falls steadily from 2.1 to 0.4, validation loss falls from 2.0 to 0.55"},{"id":"e2","label":"Training log, epochs 11 to 20","detail":"Training loss continues falling to 0.05, but validation loss rises from 0.55 back up to 0.9"},{"id":"e3","label":"Hardware log","detail":"No hardware changes occurred during the run"}],"question":"At what point does the evidence show the model beginning to overfit?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-training-deep-networks-09-o2-c1', 'mission-ai-training-deep-networks-09-o2', 1, 'multiple_choice', 'Early stopping means saving...', '{"question":"Early stopping means saving...","options":[{"id":"a","text":"The very last epoch weights, no matter what"},{"id":"b","text":"The weights from the epoch where validation loss was lowest, even if later epochs kept training"},{"id":"c","text":"Only the first epoch weights"},{"id":"d","text":"Whichever epoch finished fastest"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-ai-training-deep-networks-10-o1-c1', 'mission-ai-training-deep-networks-10-o1', 1, 'multiple_choice', 'Lowering the learning rate as training progresses mainly helps because...', '{"question":"Lowering the learning rate as training progresses mainly helps because...","options":[{"id":"a","text":"It makes the dataset smaller"},{"id":"b","text":"Large steps are useful for fast early progress, but the same size step late in training tends to overshoot or oscillate near a good minimum"},{"id":"c","text":"It guarantees the loss will reach exactly zero"},{"id":"d","text":"It removes the need for a validation set"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-10-o2-c1', 'mission-ai-training-deep-networks-10-o2', 1, 'drag_and_drop', 'Sort each learning-rate behavior into warmup, decay, or constant.', '{"items":[{"id":"i1","text":"A very small learning rate used for the first few hundred steps to avoid an early instability spike"},{"id":"i2","text":"A learning rate that decreases in a smooth curve over the whole training run"},{"id":"i3","text":"A learning rate that never changes for the entire training run"}],"targets":[{"id":"warmup","label":"Warmup"},{"id":"decay","label":"Decay"},{"id":"constant","label":"Constant, no schedule"}]}'::jsonb, '{"correctMapping":{"i1":"warmup","i2":"decay","i3":"constant"}}'::jsonb),

  ('mission-ai-training-deep-networks-11-o1-c1', 'mission-ai-training-deep-networks-11-o1', 1, 'multiple_choice', 'A complete training checkpoint should include...', '{"question":"A complete training checkpoint should include...","options":[{"id":"a","text":"Only the final validation accuracy number"},{"id":"b","text":"The model weights, the optimizer state, and the current epoch and configuration, so training or evaluation can resume correctly"},{"id":"c","text":"Only the training data"},{"id":"d","text":"Only the source code file, no weights"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-11-o2-c1', 'mission-ai-training-deep-networks-11-o2', 1, 'investigation', 'Which evidence explains what can and cannot be recovered after the crash?', '{"evidence":[{"id":"e1","label":"Crash report","detail":"Training crashed at epoch 47 due to a power outage"},{"id":"e2","label":"Checkpoint log","detail":"The last saved checkpoint, from epoch 40, includes full model weights but no optimizer state was saved"},{"id":"e3","label":"Validation log","detail":"Epoch 40 had the best validation loss of the entire run so far"}],"question":"Which evidence explains why Cipher Division can recover the best model weights but not exactly resume training from where it stopped?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-ai-training-deep-networks-12-o1-c1', 'mission-ai-training-deep-networks-12-o1', 1, 'investigation', 'Which evidence shows this network overfitting, not just training normally?', '{"evidence":[{"id":"e1","label":"Training curve","detail":"Training loss falls to 0.01 by epoch 60 and stays there, with training accuracy reaching 99.8 percent"},{"id":"e2","label":"Validation curve","detail":"Validation loss falls until epoch 15, then rises steadily from 0.4 to 1.9 by epoch 60, even as training loss keeps falling"},{"id":"e3","label":"Hardware log","detail":"No hardware or data changes occurred during the run"}],"question":"Which evidence shows this network overfitting, not just training normally?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-training-deep-networks-12-o2-c1', 'mission-ai-training-deep-networks-12-o2', 1, 'multiple_choice', 'Which single change addresses the actual failure most directly?', '{"question":"Given a network with near-zero training loss, rising validation loss, and no regularization used during training, which single change addresses the actual failure most directly?","options":[{"id":"a","text":"Increase the learning rate further"},{"id":"b","text":"Add early stopping and dropout or weight decay, and stop training at the epoch where validation loss was lowest"},{"id":"c","text":"Train for even more epochs on the same data"},{"id":"d","text":"Remove the validation set so the number cannot look bad"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-ai-training-deep-networks-12-o3-c1', 'mission-ai-training-deep-networks-12-o3', 1, 'investigation', 'Which evidence proves the fix actually improved real-world generalization?', '{"evidence":[{"id":"e1","label":"Before fix, test set","detail":"The original unregularized network scores 61 percent on a held-out test set never used during training or tuning"},{"id":"e2","label":"After fix, test set","detail":"Retrained with dropout, weight decay, and early stopping at the best validation epoch, the network scores 88 percent on the same held-out test set"},{"id":"e3","label":"Training accuracy after fix","detail":"Training accuracy after the fix drops to 93 percent, no longer near-perfect"}],"question":"Which evidence proves the fix actually improved real-world generalization, not just the training number?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-ai-training-deep-networks-12-o4-c1', 'mission-ai-training-deep-networks-12-o4', 1, 'boss_encounter', 'Having diagnosed the overfit signature, chosen the fix, and confirmed it with honest evaluation, state Cipher Division''s verdict.', '{"stages":[{"objectiveRef":"mission-ai-training-deep-networks-12-o1","label":"Diagnose the overfit signature"},{"objectiveRef":"mission-ai-training-deep-networks-12-o2","label":"Choose the fix"},{"objectiveRef":"mission-ai-training-deep-networks-12-o3","label":"Confirm the fix with honest evaluation"}],"task":"State the verdict in one sentence: unregularized and trained too long, the network memorized its training set and failed on anything new, the same lesson Act 6 taught with a spreadsheet, now true of a network with thousands of parameters, and the fix, early stopping plus dropout or weight decay, recovers real, honestly-measured performance."}'::jsonb, '{"requiredObjectiveIds":["mission-ai-training-deep-networks-12-o1","mission-ai-training-deep-networks-12-o2","mission-ai-training-deep-networks-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-ai-training-deep-networks-01-o1-c1', 'orientation', 'Look for evidence that directly shows neurons behaving identically to each other, not just evidence about training speed.', 10, 1),
  ('mission-ai-training-deep-networks-01-o1-c1', 'solution', 'e1: every neuron in the layer still outputs the exact identical value after 50 epochs -- that is the symmetry trap, and it never breaks on its own.', 20, 2),
  ('mission-ai-training-deep-networks-01-o2-c1', 'orientation', 'Think about what happens to a signal after it passes through many layers if every layer either shrinks or grows it a little.', 10, 1),
  ('mission-ai-training-deep-networks-01-o2-c1', 'solution', 'Correctly scaled initialization keeps activations and gradients in a healthy range across many stacked layers, instead of shrinking or growing at every step.', 20, 2),

  ('mission-ai-training-deep-networks-02-o1-c1', 'orientation', 'Compare the gradient size near the output layer to the gradient size near the input layer.', 10, 1),
  ('mission-ai-training-deep-networks-02-o1-c1', 'concept', 'A gradient that barely changes epoch after epoch means that layer has effectively stopped learning.', 20, 2),
  ('mission-ai-training-deep-networks-02-o1-c1', 'solution', 'e1: layer 1''s gradient norm sits at 0.00003 and barely moves, while layer 8''s is a healthy 0.42 -- that gap is the vanishing gradient signature.', 30, 3),
  ('mission-ai-training-deep-networks-02-o2-c1', 'orientation', 'Saturating activation functions are the classic cause -- ask what could reduce how often signals saturate.', 10, 1),
  ('mission-ai-training-deep-networks-02-o2-c1', 'solution', 'Switching early layers to a non-saturating activation like ReLU, and adding normalization, keeps signals from saturating and losing their gradient.', 20, 2),

  ('mission-ai-training-deep-networks-03-o1-c1', 'orientation', 'A doubling weight magnitude every epoch is a much stronger signal of runaway growth than a single NaN event alone.', 10, 1),
  ('mission-ai-training-deep-networks-03-o1-c1', 'solution', 'e2: weight magnitude doubling every epoch for three straight epochs is the direct signature of gradients exploding, not just some unrelated bug.', 20, 2),
  ('mission-ai-training-deep-networks-03-o2-c1', 'orientation', 'Look for the fix that directly caps update size, rather than one that just changes how the network starts or how fast it moves overall.', 10, 1),
  ('mission-ai-training-deep-networks-03-o2-c1', 'solution', 'Gradient clipping directly caps how large a gradient update is allowed to be, stopping the explosion before it reaches the weights.', 20, 2),

  ('mission-ai-training-deep-networks-04-o1-c1', 'orientation', 'Think about what a network''s first layer has to do differently for a feature ranging 0 to 1 versus one ranging into the hundreds of thousands.', 10, 1),
  ('mission-ai-training-deep-networks-04-o1-c1', 'solution', 'Wildly different feature scales force the network to learn very different weight scales just to treat features fairly, which slows and destabilizes training.', 20, 2),
  ('mission-ai-training-deep-networks-04-o2-c1', 'orientation', 'Compare the raw feature ranges to what changed between the before and after training logs.', 10, 1),
  ('mission-ai-training-deep-networks-04-o2-c1', 'solution', 'e1: income and age sit on wildly different raw scales with no scaling applied -- that mismatch is what the before and after logs trace back to.', 20, 2),

  ('mission-ai-training-deep-networks-05-o1-c1', 'orientation', 'Batch Norm reaches for statistics from somewhere specific -- ask which set of activations it is computing over.', 10, 1),
  ('mission-ai-training-deep-networks-05-o1-c1', 'solution', 'Batch Norm computes mean and variance across the current mini-batch for each feature, then rescales with two learnable parameters.', 20, 2),
  ('mission-ai-training-deep-networks-05-o2-c1', 'orientation', 'A statistic computed from only 4 examples is going to look very different from one batch to the next.', 10, 1),
  ('mission-ai-training-deep-networks-05-o2-c1', 'solution', 'e2: with only 4 examples per mini-batch, the per-batch mean and variance swing wildly from batch to batch, which is exactly what makes Batch Norm unstable at small batch sizes.', 20, 2),

  ('mission-ai-training-deep-networks-06-o1-c1', 'orientation', 'Layer Norm changes which axis gets normalized compared to Batch Norm -- think per-example, not per-batch.', 10, 1),
  ('mission-ai-training-deep-networks-06-o1-c1', 'solution', 'Layer Norm computes its statistics across all the features of one single example, so it never depends on batch size at all.', 20, 2),
  ('mission-ai-training-deep-networks-06-o2-c1', 'orientation', 'Ask whether each scenario has a large, stable batch to draw statistics from, or needs to behave the same regardless of batch size.', 10, 1),
  ('mission-ai-training-deep-networks-06-o2-c1', 'solution', 'Batch Norm fits large, stable-batch convolutional settings. Layer Norm fits small or variable batches, and anywhere training and single-example inference must match exactly.', 20, 2),

  ('mission-ai-training-deep-networks-07-o1-c1', 'orientation', 'Think about what happens to a network that can always lean on one specific neuron being present.', 10, 1),
  ('mission-ai-training-deep-networks-07-o1-c1', 'solution', 'Randomly zeroing activations during training prevents the network from over-relying on any one neuron or fixed combination of them, which is what actually improves generalization.', 20, 2),
  ('mission-ai-training-deep-networks-07-o2-c1', 'orientation', 'A frozen, properly deployed model should give the exact same output for the exact same input, every time.', 10, 1),
  ('mission-ai-training-deep-networks-07-o2-c1', 'solution', 'e2: dropout was left active during inference instead of being disabled, so the same input produces a different random subset of active neurons, and a different output, every call.', 20, 2),

  ('mission-ai-training-deep-networks-08-o1-c1', 'orientation', 'The mechanism is a term added directly to the loss, not a change to which neurons are active.', 10, 1),
  ('mission-ai-training-deep-networks-08-o1-c1', 'solution', 'Weight decay adds a penalty proportional to the squared weight magnitudes to the loss, which nudges every weight a little smaller on every step.', 20, 2),
  ('mission-ai-training-deep-networks-08-o2-c1', 'orientation', 'Compare weight magnitude and the training/validation gap before and after weight decay was added.', 10, 1),
  ('mission-ai-training-deep-networks-08-o2-c1', 'solution', 'e2: after adding weight decay, average weight magnitude drops sharply and the training/validation gap shrinks from about 19 points to about 6 points -- a real, measurable regularizing effect.', 20, 2),

  ('mission-ai-training-deep-networks-09-o1-c1', 'orientation', 'Look for the exact log entry where validation loss changes direction while training loss does not.', 10, 1),
  ('mission-ai-training-deep-networks-09-o1-c1', 'concept', 'Widening gap between training loss still falling and validation loss now rising is the actual signal, not either curve alone.', 20, 2),
  ('mission-ai-training-deep-networks-09-o1-c1', 'solution', 'e2: between epochs 11 and 20, training loss keeps falling to 0.05 while validation loss reverses and climbs from 0.55 to 0.9 -- that is the overfitting turning point.', 30, 3),
  ('mission-ai-training-deep-networks-09-o2-c1', 'orientation', 'Early stopping is not about when training halts, it is about which epoch weights actually get kept.', 10, 1),
  ('mission-ai-training-deep-networks-09-o2-c1', 'solution', 'Early stopping keeps the weights from whichever epoch had the lowest validation loss, even if training was allowed to continue past that point.', 20, 2),

  ('mission-ai-training-deep-networks-10-o1-c1', 'orientation', 'Think about what a large step size does once training is already close to a good solution.', 10, 1),
  ('mission-ai-training-deep-networks-10-o1-c1', 'solution', 'Big steps help early on, but that same step size late in training tends to overshoot or bounce around near a good minimum instead of settling into it.', 20, 2),
  ('mission-ai-training-deep-networks-10-o2-c1', 'orientation', 'Ask whether each behavior ramps up, ramps down, or never changes at all.', 10, 1),
  ('mission-ai-training-deep-networks-10-o2-c1', 'solution', 'Warmup ramps up briefly at the start. Decay lowers the rate smoothly over the run. Constant never changes it at all.', 20, 2),

  ('mission-ai-training-deep-networks-11-o1-c1', 'orientation', 'A checkpoint needs to support resuming training correctly, not just reproducing predictions.', 10, 1),
  ('mission-ai-training-deep-networks-11-o1-c1', 'solution', 'A complete checkpoint saves the model weights, the optimizer state, and the current epoch and configuration -- skip the optimizer state and a resumed run will not behave the same as an uninterrupted one.', 20, 2),
  ('mission-ai-training-deep-networks-11-o2-c1', 'orientation', 'Separate what the missing piece of the checkpoint affects from what it does not.', 10, 1),
  ('mission-ai-training-deep-networks-11-o2-c1', 'solution', 'e2: epoch 40''s checkpoint has the model weights but no optimizer state, so Cipher Division can recover the best-performing weights, but cannot resume training from exactly where it left off.', 20, 2),

  ('mission-ai-training-deep-networks-12-o1-c1', 'orientation', 'A near-zero training loss by itself is not the overfit signature -- look for what validation is doing at the same time.', 10, 1),
  ('mission-ai-training-deep-networks-12-o1-c1', 'concept', 'A powerful model can legitimately reach very low training loss; what turns that into overfitting is what happens to validation loss at the same time.', 20, 2),
  ('mission-ai-training-deep-networks-12-o1-c1', 'solution', 'e2: validation loss falls until epoch 15 and then climbs steadily even as training loss keeps dropping -- that widening gap is the overfit signature, not the training number alone.', 30, 3),
  ('mission-ai-training-deep-networks-12-o2-c1', 'orientation', 'The fix needs to address both when training stops and what discourages memorization while it runs.', 10, 1),
  ('mission-ai-training-deep-networks-12-o2-c1', 'solution', 'Adding early stopping alongside dropout or weight decay, and keeping the best-validation-epoch checkpoint, directly targets the overfitting shown in the curves.', 20, 2),
  ('mission-ai-training-deep-networks-12-o3-c1', 'orientation', 'The proof has to come from data the fix was never tuned against.', 10, 1),
  ('mission-ai-training-deep-networks-12-o3-c1', 'concept', 'A test set only proves something if it was never touched during training or tuning -- otherwise the fix could just be memorizing that set too.', 20, 2),
  ('mission-ai-training-deep-networks-12-o3-c1', 'solution', 'e2: on the same held-out test set never used during training or tuning, the fixed network scores 88 percent versus the original 61 percent -- a real improvement measured honestly, not just an assertion.', 30, 3),
  ('mission-ai-training-deep-networks-12-o4-c1', 'orientation', 'Weigh all three checks together: what the curves showed, what fixed it, and what the honest evaluation proved.', 15, 1),
  ('mission-ai-training-deep-networks-12-o4-c1', 'solution', 'Left unregularized and trained too long, the network memorized its training set and collapsed on anything new. Early stopping plus dropout or weight decay fixed it, and a held-out test set confirms the fix is real: the same lesson Act 6 taught with a spreadsheet, now proven true of a network with thousands of parameters.', 25, 2);
